-- Aprenda se Divertindo · 38 · Trilha Saúde · lote 1 (100 questões)
-- Base: concurso da Prefeitura de Salvador (SMS, banca IDECAN). Foco em Enfermagem, com Legislação do SUS, Medicina e Fisioterapia.
-- Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.

-- libera a trilha saude nas partidas e nas disputas
alter table public.partidas drop constraint if exists partidas_trilha_check;
alter table public.partidas add constraint partidas_trilha_check check (trilha in ('geral','pcba','trf4','policial','tribunais','fiscal','enem','administrativa','saude'));
alter table public.partidas_anonimas drop constraint if exists partidas_anonimas_trilha_check;
alter table public.partidas_anonimas add constraint partidas_anonimas_trilha_check check (trilha in ('geral','pcba','trf4','policial','tribunais','fiscal','enem','administrativa','saude'));
alter table public.disputas drop constraint if exists disputas_trilha_check;
alter table public.disputas add constraint disputas_trilha_check check (trilha in ('geral','policial','tribunais','fiscal','enem','administrativa','saude'));

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":4639,"materia":"sus","nivel":0,"enunciado":"A Lei nº 8.080/1990 dispõe sobre:","opcoes":["As condições para a promoção, proteção e recuperação da saúde e a organização e o funcionamento dos serviços","A participação da comunidade na gestão do SUS e as transferências de recursos entre os governos federal, estaduais e municipais","O Estatuto do Servidor Público municipal","A criação dos planos de saúde privados"],"explicacao":"É a Lei Orgânica da Saúde. A participação da comunidade e as transferências estão na Lei nº 8.142/1990."},{"id":4640,"materia":"sus","nivel":0,"enunciado":"A Lei nº 8.142/1990 trata principalmente:","opcoes":["Da participação da comunidade na gestão do SUS e das transferências intergovernamentais de recursos","Da organização dos hospitais universitários e da formação de residentes em saúde","Do exercício profissional da enfermagem","Do Código de Ética Médica"],"explicacao":"Ela criou as Conferências e os Conselhos de Saúde como instâncias colegiadas."},{"id":4641,"materia":"sus","nivel":0,"enunciado":"Pela Constituição Federal (art. 196), a saúde é:","opcoes":["Direito de todos e dever do Estado","Um serviço pago para quem pode contribuir","Responsabilidade exclusiva das famílias","Direito apenas de quem tem carteira assinada"],"explicacao":"Garantida por políticas sociais e econômicas e acesso universal e igualitário."},{"id":4642,"materia":"sus","nivel":0,"enunciado":"O princípio da universalidade do SUS significa:","opcoes":["Acesso aos serviços de saúde para todas as pessoas, sem discriminação","Atendimento só para quem contribui com o INSS e tem carteira de trabalho assinada","Atendimento apenas em casos de urgência","Serviços iguais em todas as cidades do mundo"],"explicacao":"Antes do SUS, a assistência pública era ligada à contribuição previdenciária."},{"id":4643,"materia":"sus","nivel":0,"enunciado":"As Conferências de Saúde, previstas na Lei nº 8.142/1990, se reúnem:","opcoes":["A cada quatro anos","Todo mês","Uma vez por semana","Apenas em epidemias"],"explicacao":"Avaliam a situação de saúde e propõem diretrizes para as políticas de saúde."},{"id":4644,"materia":"sus","nivel":0,"enunciado":"O Conselho de Saúde tem caráter:","opcoes":["Permanente e deliberativo","Provisório e apenas consultivo","Privado e lucrativo","Exclusivamente técnico, sem participação de usuários"],"explicacao":"Atua na formulação de estratégias e no controle da execução da política de saúde."},{"id":4645,"materia":"sus","nivel":0,"enunciado":"A integralidade, no SUS, é:","opcoes":["O conjunto articulado de ações e serviços preventivos e curativos, individuais e coletivos","O atendimento apenas de doenças graves","A oferta de serviços só nas capitais","O pagamento integral das consultas pelo próprio paciente, sem ajuda do governo"],"explicacao":"Considera a pessoa como um todo, em todos os níveis de complexidade."},{"id":4646,"materia":"sus","nivel":0,"enunciado":"Tratar de forma diferente quem tem necessidades diferentes, para reduzir desigualdades, é o princípio da:","opcoes":["Equidade","Universalidade","Hierarquização","Centralização"],"explicacao":"Prioriza quem mais precisa."},{"id":4647,"materia":"sus","nivel":0,"enunciado":"Segundo a PNAB 2017, a Atenção Básica é:","opcoes":["A principal porta de entrada e o centro de comunicação da Rede de Atenção à Saúde","Um serviço só para emergências","O último nível de atendimento","Um setor exclusivo de exames de imagem e de cirurgias de alta complexidade"],"explicacao":"Coordena o cuidado e ordena as ações e serviços da rede."},{"id":4648,"materia":"sus","nivel":1,"enunciado":"Nos Conselhos e Conferências de Saúde, a representação dos usuários é:","opcoes":["Paritária em relação ao conjunto dos demais segmentos","Inexistente","Limitada a um único representante","Maior que a de todos os outros segmentos juntos, sempre em dobro"],"explicacao":"Usuários ocupam 50% das vagas."},{"id":4649,"materia":"sus","nivel":1,"enunciado":"O Decreto nº 7.508/2011:","opcoes":["Regulamenta a Lei nº 8.080/1990 na organização do SUS, planejamento, assistência e articulação interfederativa","Revoga a Lei nº 8.080/1990","Cria os planos de saúde","Trata apenas da vacinação infantil e do calendário de imunização nas escolas públicas do país"],"explicacao":"Define, por exemplo, Região de Saúde e as Portas de Entrada do SUS."},{"id":4650,"materia":"sus","nivel":1,"enunciado":"Pela Constituição, a descentralização do SUS ocorre:","opcoes":["Com direção única em cada esfera de governo","Com comando único federal para todo o país, sem gestão local","Sem participação dos municípios","Apenas na área hospitalar"],"explicacao":"Art. 198, I."},{"id":4651,"materia":"sus","nivel":1,"enunciado":"Na participação complementar da iniciativa privada no SUS, têm preferência:","opcoes":["As entidades filantrópicas e as sem fins lucrativos","As empresas estrangeiras","As clínicas com maior lucro e as empresas de capital estrangeiro","Os planos de saúde"],"explicacao":"Art. 199, § 1º, da Constituição."},{"id":4652,"materia":"sus","nivel":1,"enunciado":"A PNAB 2017 recomenda que cada Equipe de Saúde da Família seja responsável por:","opcoes":["2.000 a 3.500 pessoas","500 a 1.000 pessoas","10.000 a 15.000 pessoas","Toda a população do município"],"explicacao":"Considerando o grau de vulnerabilidade do território."},{"id":4653,"materia":"sus","nivel":1,"enunciado":"A Política Nacional de Humanização (HumanizaSUS) tem como uma de suas diretrizes:","opcoes":["O acolhimento, com escuta qualificada e responsabilização pelo cuidado","A redução das equipes multiprofissionais","O atendimento só por ordem de chegada, sem avaliar o risco nem a vulnerabilidade de cada pessoa","A proibição de acompanhantes"],"explicacao":"Também valoriza a clínica ampliada e a cogestão."},{"id":4654,"materia":"sus","nivel":1,"enunciado":"A notificação compulsória de doenças e agravos é obrigatória para:","opcoes":["Médicos, outros profissionais de saúde e responsáveis por estabelecimentos de saúde","Apenas os médicos que trabalham em hospitais públicos de grande porte","Somente os próprios pacientes","Apenas os laboratórios particulares"],"explicacao":"Também se aplica a instituições de ensino e pesquisa."},{"id":4655,"materia":"sus","nivel":2,"enunciado":"Segundo a Lei nº 8.080/1990, a vigilância sanitária é o conjunto de ações capaz de:","opcoes":["Eliminar, diminuir ou prevenir riscos à saúde decorrentes do meio ambiente, da produção e circulação de bens e da prestação de serviços","Apenas registrar nascimentos e óbitos nos cartórios, sem nenhuma ação de fiscalização sobre produtos, serviços ou ambientes de trabalho","Somente vacinar a população","Contratar médicos para hospitais"],"explicacao":"A vigilância epidemiológica acompanha os fatores que determinam doenças."},{"id":4656,"materia":"sus","nivel":2,"enunciado":"A Comissão Intergestores Tripartite (CIT) reúne gestores:","opcoes":["Da União, dos estados e dos municípios","Apenas dos municípios de uma região","Dos hospitais privados","Dos conselhos de classe profissionais e dos sindicatos"],"explicacao":"A Bipartite (CIB) reúne estado e municípios."},{"id":4657,"materia":"sus","nivel":2,"enunciado":"A Carta dos Direitos dos Usuários da Saúde garante, entre outros pontos:","opcoes":["Acesso ordenado e organizado aos sistemas de saúde e tratamento adequado","Atendimento só com indicação política","Prioridade a quem paga mais impostos","O direito de escolher o salário do médico e o horário de funcionamento da unidade"],"explicacao":"Também garante atendimento humanizado e sem discriminação."},{"id":4658,"materia":"sus","nivel":2,"enunciado":"O marco do Movimento da Reforma Sanitária que inspirou a criação do SUS foi:","opcoes":["A 8ª Conferência Nacional de Saúde, em 1986","A Revolta da Vacina, no Rio de Janeiro, em 1904","A criação do INAMPS, em 1977","A Lei Áurea, em 1888"],"explicacao":"Suas propostas foram levadas à Constituinte de 1988."},{"id":4659,"materia":"sus","nivel":3,"enunciado":"Pela Lei Complementar nº 141/2012, os municípios devem aplicar em ações e serviços públicos de saúde, no mínimo:","opcoes":["15% da receita de impostos e transferências","5% da receita","50% da receita","1% do PIB municipal, a cada quatro anos"],"explicacao":"Os estados, no mínimo 12%."},{"id":4660,"materia":"sus","nivel":3,"enunciado":"Segundo o Decreto nº 7.508/2011, são Portas de Entrada às ações e serviços de saúde, entre outras:","opcoes":["Atenção primária, urgência e emergência, e atenção psicossocial","Apenas os hospitais de alta complexidade e os ambulatórios de especialidades","Somente as farmácias","Os consultórios particulares"],"explicacao":"Também os serviços especiais de acesso aberto."},{"id":4661,"materia":"sus","nivel":3,"enunciado":"Nas Redes de Atenção à Saúde (Portaria nº 4.279/2010), a atenção primária atua como:","opcoes":["Centro de comunicação, coordenando o cuidado","Um nível isolado, sem relação com os demais pontos da rede","Serviço exclusivo de alta complexidade","Porta de saída do sistema"],"explicacao":"As redes são organizadas de forma poliárquica, não hierárquica rígida."},{"id":4662,"materia":"sus","nivel":4,"enunciado":"Para receber recursos do Fundo Nacional de Saúde, a Lei nº 8.142/1990 exige que os municípios tenham, entre outros:","opcoes":["Fundo de Saúde, Conselho de Saúde, plano de saúde e relatórios de gestão","Apenas um hospital próprio","Um plano de saúde privado contratado para todos os servidores municipais","Uma faculdade de medicina"],"explicacao":"Também contrapartida de recursos e comissão para o plano de carreira."},{"id":4663,"materia":"sus","nivel":4,"enunciado":"A Política Nacional de Saúde Integral da População Negra tem como marca:","opcoes":["Reconhecer o racismo como determinante social das condições de saúde","Criar serviços separados por cor da pele","Tratar apenas a doença falciforme","Excluir a população negra das demais políticas e programas de saúde do SUS"],"explicacao":"Busca promover a equidade em saúde."},{"id":4664,"materia":"enf","nivel":0,"enunciado":"A lei que regulamenta o exercício da enfermagem no Brasil é a:","opcoes":["Lei nº 7.498/1986","Lei nº 8.080/1990","Lei nº 8.142/1990","Lei nº 10.741/2003"],"explicacao":"Regulamentada pelo Decreto nº 94.406/1987."},{"id":4665,"materia":"enf","nivel":0,"enunciado":"O Código de Ética dos Profissionais de Enfermagem em vigor foi aprovado pela:","opcoes":["Resolução Cofen nº 564/2017","Lei nº 7.498/1986","Resolução CFM nº 2.217/2018","Portaria nº 2.436/2017"],"explicacao":"A Resolução CFM nº 2.217/2018 é o Código de Ética Médica."},{"id":4666,"materia":"enf","nivel":0,"enunciado":"A medida isolada mais importante para prevenir infecções relacionadas à assistência à saúde é:","opcoes":["A higienização das mãos","O uso de antibióticos preventivos em todos","O uso de luvas o tempo todo","Manter as janelas fechadas"],"explicacao":"Luvas não substituem a higienização das mãos."},{"id":4667,"materia":"enf","nivel":0,"enunciado":"A frequência respiratória considerada normal em um adulto em repouso é de:","opcoes":["12 a 20 incursões por minuto","4 a 8 incursões por minuto","30 a 40 incursões por minuto","60 a 100 incursões por minuto"],"explicacao":"Abaixo é bradipneia; acima, taquipneia."},{"id":4668,"materia":"enf","nivel":0,"enunciado":"Em lactentes, o local preferido para injeção intramuscular é o músculo:","opcoes":["Vasto lateral da coxa","Deltoide","Glúteo máximo","Peitoral maior, no tórax"],"explicacao":"É bem desenvolvido e distante de grandes vasos e nervos."},{"id":4669,"materia":"enf","nivel":0,"enunciado":"Pela Lei nº 7.498/1986, a consulta de enfermagem é atividade:","opcoes":["Privativa do enfermeiro","Do técnico de enfermagem","Do auxiliar de enfermagem","De qualquer profissional de saúde"],"explicacao":"Também são privativas a prescrição da assistência de enfermagem e os cuidados de maior complexidade técnica."},{"id":4670,"materia":"enf","nivel":0,"enunciado":"Ao nascer, o recém-nascido deve receber as vacinas:","opcoes":["BCG e hepatite B","Tríplice viral e febre amarela","HPV e dTpa","Pneumocócica 23 e influenza"],"explicacao":"A hepatite B, de preferência nas primeiras 24 horas."},{"id":4671,"materia":"enf","nivel":0,"enunciado":"Para prevenir lesão por pressão em paciente acamado, recomenda-se:","opcoes":["Mudar a posição (decúbito) regularmente, por exemplo a cada 2 horas","Manter o paciente sempre na mesma posição para não incomodar o descanso","Massagear com força as áreas avermelhadas","Deixar a pele sempre úmida"],"explicacao":"Também se usam colchões e coxins para aliviar a pressão."},{"id":4672,"materia":"enf","nivel":0,"enunciado":"O Ministério da Saúde recomenda aleitamento materno exclusivo até:","opcoes":["Os 6 meses de vida","O 1º mês","Os 2 anos","Os 3 meses, quando começa a papinha"],"explicacao":"Depois, complementado até 2 anos ou mais."},{"id":4673,"materia":"enf","nivel":0,"enunciado":"O ácido fólico é indicado antes e no início da gestação para prevenir:","opcoes":["Defeitos do tubo neural no bebê","Diabetes gestacional e pressão alta na gravidez","Hipertensão","Infecção urinária"],"explicacao":"Ex.: espinha bífida."},{"id":4674,"materia":"enf","nivel":0,"enunciado":"O álcool a 70% é usado em procedimentos de enfermagem principalmente como:","opcoes":["Antisséptico e desinfetante","Anestésico","Anticoagulante","Antibiótico de uso oral para infecções graves"],"explicacao":"Na concentração de 70%, age melhor que o álcool puro."},{"id":4675,"materia":"enf","nivel":0,"enunciado":"A glicemia de jejum considerada normal é:","opcoes":["Menor que 100 mg/dL","Entre 150 e 200 mg/dL","Maior que 126 mg/dL","Acima de 300 mg/dL"],"explicacao":"A partir de 126 mg/dL (confirmado) indica diabetes."},{"id":4676,"materia":"enf","nivel":0,"enunciado":"Na posição de Fowler, o paciente fica:","opcoes":["Semissentado, com a cabeceira elevada","Deitado de bruços","Com a cabeça mais baixa que os pés","Deitado de lado com uma perna dobrada"],"explicacao":"Facilita a respiração."},{"id":4677,"materia":"enf","nivel":0,"enunciado":"A escala de coma de Glasgow varia de:","opcoes":["3 a 15 pontos","0 a 10 pontos","1 a 5 pontos","10 a 100 pontos"],"explicacao":"Avalia abertura ocular, resposta verbal e resposta motora."},{"id":4678,"materia":"enf","nivel":0,"enunciado":"Na posição de Trendelenburg, o paciente fica:","opcoes":["Deitado de costas, com a cabeça mais baixa que os pés","Sentado, com as pernas para baixo e as costas apoiadas na cadeira","Deitado de lado","Em pé, apoiado"],"explicacao":"Usada em algumas cirurgias e situações específicas."},{"id":4679,"materia":"enf","nivel":1,"enunciado":"Os 5 momentos para a higienização das mãos (OMS) incluem:","opcoes":["Antes de tocar o paciente e após risco de exposição a fluidos corporais","Apenas ao chegar e ao sair do plantão, quando as mãos estiverem visivelmente sujas","Só depois de usar o banheiro","Apenas antes das refeições"],"explicacao":"Também antes de procedimento asséptico, após tocar o paciente e após tocar superfícies próximas a ele."},{"id":4680,"materia":"enf","nivel":1,"enunciado":"Prescrição: 500 mg de um antibiótico. O frasco tem 1 g diluído em 10 mL. Devem ser aspirados:","opcoes":["5 mL","10 mL","2 mL","50 mL"],"explicacao":"1 g = 1.000 mg em 10 mL → 100 mg/mL."},{"id":4681,"materia":"enf","nivel":1,"enunciado":"Para infundir 1.000 mL de soro em 8 horas, com equipo de macrogotas, o gotejamento é de aproximadamente:","opcoes":["42 gotas/min","21 gotas/min","125 gotas/min","83 gotas/min"],"explicacao":"Gotas/min = volume ÷ (horas × 3) = 1.000 ÷ 24."},{"id":4682,"materia":"enf","nivel":1,"enunciado":"Em equipo de microgotas, 120 mL em 2 horas correspondem a:","opcoes":["60 microgotas/min","120 microgotas/min","20 microgotas/min","240 microgotas/min"],"explicacao":"Microgotas/min = volume ÷ horas."},{"id":4683,"materia":"enf","nivel":1,"enunciado":"Para paciente com tuberculose pulmonar bacilífera, o profissional deve usar:","opcoes":["Máscara N95/PFF2 (precaução por aerossóis)","Apenas máscara cirúrgica","Somente luvas","Nenhuma proteção especial além do jaleco comum"],"explicacao":"Sarampo e varicela também exigem precaução por aerossóis."},{"id":4684,"materia":"enf","nivel":1,"enunciado":"O teste do pezinho deve ser coletado, de preferência, entre:","opcoes":["O 3º e o 5º dia de vida","O 1º e o 2º mês","As primeiras 6 horas de vida","O 6º e o 12º mês"],"explicacao":"Detecta doenças como fenilcetonúria, hipotireoidismo congênito e doença falciforme."},{"id":4685,"materia":"enf","nivel":1,"enunciado":"O tratamento da sífilis em gestante é feito com:","opcoes":["Penicilina benzatina","Paracetamol","Insulina","Sulfato ferroso e vitaminas"],"explicacao":"Também é preciso tratar a parceria sexual."},{"id":4686,"materia":"enf","nivel":1,"enunciado":"No exame físico do abdome, a sequência correta é:","opcoes":["Inspeção, ausculta, percussão e palpação","Palpação, percussão, ausculta e inspeção","Percussão, palpação, inspeção e ausculta","Ausculta, palpação, inspeção e percussão"],"explicacao":"A ausculta vem antes para não alterar os ruídos intestinais."},{"id":4687,"materia":"enf","nivel":1,"enunciado":"A meningite meningocócica exige precaução por:","opcoes":["Gotículas","Aerossóis","Apenas contato","Nenhuma precaução"],"explicacao":"Mantida até 24 horas de antibiótico eficaz."},{"id":4688,"materia":"enf","nivel":1,"enunciado":"O registro de enfermagem que pode ser feito por técnicos e auxiliares, descrevendo cuidados e observações, é a:","opcoes":["Anotação de enfermagem","Evolução de enfermagem","Prescrição de enfermagem","Consulta de enfermagem"],"explicacao":"A evolução e a prescrição são do enfermeiro."},{"id":4689,"materia":"enf","nivel":1,"enunciado":"Na classificação de risco pelo Protocolo de Manchester, a cor vermelha indica:","opcoes":["Emergência, com atendimento imediato","Caso não urgente","Atendimento em até 4 horas, sem prioridade","Alta hospitalar"],"explicacao":"Depois vêm laranja, amarelo, verde e azul."},{"id":4690,"materia":"enf","nivel":2,"enunciado":"Na escala de Braden, quanto menor o escore:","opcoes":["Maior o risco de lesão por pressão","Menor o risco de lesão por pressão","Melhor o nível de consciência","Maior a força muscular"],"explicacao":"Avalia percepção sensorial, umidade, atividade, mobilidade, nutrição e fricção."},{"id":4691,"materia":"enf","nivel":2,"enunciado":"Na RCP em adulto, as compressões torácicas devem ter frequência de:","opcoes":["100 a 120 por minuto, com profundidade de 5 a 6 cm","60 a 80 por minuto, com 2 cm de profundidade e pausas longas entre as séries","150 a 180 por minuto, superficiais","30 por minuto, com 10 cm de profundidade"],"explicacao":"Sem via aérea avançada, a relação é de 30 compressões para 2 ventilações."},{"id":4692,"materia":"enf","nivel":2,"enunciado":"Entre as insulinas abaixo, a que pode ser administrada por via intravenosa é a:","opcoes":["Regular","NPH","Glargina","Detemir"],"explicacao":"A NPH é só subcutânea."},{"id":4693,"materia":"enf","nivel":2,"enunciado":"Em hipoglicemia leve com paciente consciente, a conduta inicial recomendada é oferecer:","opcoes":["Cerca de 15 g de carboidrato de absorção rápida e reavaliar em 15 minutos","Insulina regular","Uma refeição gordurosa e aguardar 2 horas antes de medir de novo a glicemia","Apenas água"],"explicacao":"Regra dos 15."},{"id":4694,"materia":"enf","nivel":2,"enunciado":"Uma lesão por pressão com perda parcial da espessura da pele e derme exposta é classificada como estágio:","opcoes":["2","1","3","4"],"explicacao":"No estágio 1, a pele está íntegra com eritema que não embranquece."},{"id":4695,"materia":"enf","nivel":2,"enunciado":"O sulfato de magnésio é usado na pré-eclâmpsia grave para:","opcoes":["Prevenir convulsões (eclâmpsia)","Baixar a glicemia","Induzir o parto","Tratar infecção urinária de repetição"],"explicacao":"Em caso de intoxicação, o antídoto é o gluconato de cálcio."},{"id":4696,"materia":"enf","nivel":2,"enunciado":"Pela Lei nº 7.498/1986, as atividades do técnico e do auxiliar de enfermagem em instituições de saúde:","opcoes":["Só podem ser realizadas sob orientação e supervisão do enfermeiro","Dispensam qualquer supervisão","São supervisionadas apenas pelo médico responsável pelo plantão do setor","Incluem a prescrição da assistência"],"explicacao":"Art. 15 da lei."},{"id":4697,"materia":"enf","nivel":3,"enunciado":"Penicilina cristalina 5.000.000 UI: ao diluir com 8 mL, o volume final é de 10 mL. Para administrar 2.000.000 UI, aspiram-se:","opcoes":["4 mL","2 mL","8 mL","5 mL"],"explicacao":"O pó ocupa cerca de 2 mL. 5.000.000 UI em 10 mL → 500.000 UI/mL."},{"id":4698,"materia":"enf","nivel":3,"enunciado":"No choque anafilático, o medicamento de primeira escolha é a:","opcoes":["Adrenalina por via intramuscular","Dipirona intravenosa em dose alta","Insulina subcutânea","Furosemida oral"],"explicacao":"De preferência no vasto lateral da coxa."},{"id":4699,"materia":"enf","nivel":3,"enunciado":"A escala de Apgar é aplicada no recém-nascido:","opcoes":["No 1º e no 5º minuto de vida","Apenas no 7º dia","No 1º mês","Somente se houver febre no primeiro dia"],"explicacao":"Avalia frequência cardíaca, respiração, tônus, irritabilidade reflexa e cor."},{"id":4700,"materia":"enf","nivel":3,"enunciado":"Pela Lei nº 7.498/1986, o enfermeiro pode prescrever medicamentos:","opcoes":["Estabelecidos em programas de saúde pública e em rotina aprovada pela instituição","Livremente, sem nenhuma restrição","Apenas antibióticos de uso hospitalar, sem protocolo e por conta própria em qualquer serviço","Nunca, em nenhuma situação"],"explicacao":"Como integrante da equipe de saúde."},{"id":4701,"materia":"enf","nivel":4,"enunciado":"Uma criança de 20 kg tem prescrição de 15 mg/kg de paracetamol. A solução tem 200 mg/mL. A dose em mL é de:","opcoes":["1,5 mL","3 mL","0,75 mL","15 mL"],"explicacao":"20 × 15 = 300 mg; 300 ÷ 200 = 1,5 mL."},{"id":4702,"materia":"enf","nivel":4,"enunciado":"No período pós-parto, a involução uterina esperada é que o fundo do útero, por volta do 10º dia, esteja:","opcoes":["Na altura da sínfise púbica ou não palpável pelo abdome","Acima da cicatriz umbilical","Na altura do apêndice xifoide","Do mesmo tamanho do fim da gestação, acima do umbigo"],"explicacao":"Logo após o parto, fica próximo à cicatriz umbilical."},{"id":4703,"materia":"enf","nivel":4,"enunciado":"Na estratégia AIDPI, é um sinal geral de perigo na criança de 2 meses a 5 anos:","opcoes":["Não conseguir beber nem mamar","Ter coriza clara há um dia","Espirrar algumas vezes ao dia","Ter apetite um pouco menor que o habitual"],"explicacao":"Também: vomitar tudo, ter convulsões ou estar letárgica ou inconsciente. Exige encaminhamento urgente."},{"id":4704,"materia":"fisio","nivel":0,"enunciado":"Na fase aguda de uma entorse (primeiras 48 a 72 horas), a crioterapia ajuda a:","opcoes":["Reduzir dor e edema","Aumentar a inflamação","Aquecer a articulação","Fortalecer o músculo"],"explicacao":"O calor costuma ser evitado nessa fase."},{"id":4705,"materia":"fisio","nivel":0,"enunciado":"O TENS (estimulação elétrica nervosa transcutânea) é usado principalmente para:","opcoes":["Alívio da dor","Aumentar a pressão arterial","Tratar infecções","Fazer diagnósticos de imagem"],"explicacao":"Atua pela teoria das comportas da dor."},{"id":4706,"materia":"fisio","nivel":0,"enunciado":"Os exercícios de Kegel fortalecem a musculatura:","opcoes":["Do assoalho pélvico","Do ombro","Da panturrilha e do tornozelo","Do pescoço"],"explicacao":"Ajudam na incontinência urinária."},{"id":4707,"materia":"fisio","nivel":0,"enunciado":"Uma pessoa com dor no joelho direito deve usar a bengala:","opcoes":["Na mão esquerda","Na mão direita","Nas duas mãos alternadamente","Presa à perna direita"],"explicacao":"Do lado oposto ao membro afetado, para dividir a carga."},{"id":4708,"materia":"fisio","nivel":0,"enunciado":"O incentivador inspiratório, no pós-operatório, ajuda a prevenir:","opcoes":["Atelectasia (colapso dos alvéolos)","Fratura de fêmur","Diabetes","Hipertensão arterial e diabetes"],"explicacao":"Estimula inspirações profundas."},{"id":4709,"materia":"fisio","nivel":1,"enunciado":"O calor superficial deve ser evitado em:","opcoes":["Processos inflamatórios agudos","Contraturas musculares crônicas","Rigidez articular crônica","Dor lombar crônica"],"explicacao":"Pode aumentar o edema e a inflamação."},{"id":4710,"materia":"fisio","nivel":1,"enunciado":"Após um AVC, é comum a marcha:","opcoes":["Hemiparética (ceifante)","Anserina","Atáxica de origem cerebelar, sempre","Escarvante bilateral"],"explicacao":"O membro afetado faz um semicírculo ao avançar."},{"id":4711,"materia":"fisio","nivel":1,"enunciado":"Na hidroterapia, o empuxo da água:","opcoes":["Reduz a descarga de peso sobre as articulações","Aumenta o peso do corpo","Impede qualquer movimento","Eleva a pressão arterial em todos os pacientes"],"explicacao":"Facilita exercícios em quem tem dor ou fraqueza."},{"id":4712,"materia":"fisio","nivel":1,"enunciado":"O ultrassom terapêutico é contraindicado sobre:","opcoes":["Útero gravídico e áreas com tumor","Músculos com contratura","Tendões com tendinite crônica e dor persistente","Cicatrizes antigas"],"explicacao":"Também sobre os olhos e áreas com infecção ativa."},{"id":4713,"materia":"fisio","nivel":2,"enunciado":"A escala de Ashworth modificada avalia:","opcoes":["A espasticidade","O equilíbrio","A força de preensão","A capacidade pulmonar"],"explicacao":"Gradua a resistência ao movimento passivo."},{"id":4714,"materia":"fisio","nivel":2,"enunciado":"A escala de Berg é usada para avaliar:","opcoes":["O equilíbrio e o risco de quedas","A dor","A espasticidade dos membros superiores","A sensibilidade"],"explicacao":"Muito usada em idosos."},{"id":4715,"materia":"fisio","nivel":2,"enunciado":"A Reabilitação Baseada na Comunidade (RBC), proposta pela OMS, é uma estratégia que:","opcoes":["Usa recursos da própria comunidade para a inclusão e a reabilitação de pessoas com deficiência","Atende apenas em grandes hospitais","Exclui a família do processo","Substitui todos os serviços especializados e os centros de reabilitação do SUS por voluntários sem formação"],"explicacao":"Envolve pessoas com deficiência, famílias e serviços locais."},{"id":4716,"materia":"fisio","nivel":3,"enunciado":"Os testes de Lachman e da gaveta anterior avaliam lesão do:","opcoes":["Ligamento cruzado anterior do joelho","Manguito rotador","Tendão de Aquiles","Menisco do quadril e ligamento redondo"],"explicacao":"Detectam a translação anterior da tíbia."},{"id":4717,"materia":"fisio","nivel":3,"enunciado":"A paralisia de Erb (lesão do plexo braquial C5–C6) costuma deixar o membro na posição de:","opcoes":["'Gorjeta de garçom', com braço em rotação interna e cotovelo estendido","Mão em garra","Punho caído com dedos estendidos e polegar aduzido, típica de lesão do nervo radial","Ombro em abdução máxima"],"explicacao":"Comum em partos difíceis."},{"id":4718,"materia":"fisio","nivel":4,"enunciado":"A estimulação precoce é mais eficaz nos primeiros anos de vida porque:","opcoes":["Nessa fase a neuroplasticidade do cérebro é maior","O bebê não sente dor","Os ossos já estão totalmente formados","Não há desenvolvimento motor nem cognitivo nesse período da vida"],"explicacao":"Indicada para bebês com risco de atraso no desenvolvimento."},{"id":4719,"materia":"med","nivel":0,"enunciado":"A declaração de óbito deve ser preenchida pelo:","opcoes":["Médico","Enfermeiro","Técnico de enfermagem","Familiar do falecido"],"explicacao":"É documento médico e base das estatísticas de mortalidade."},{"id":4720,"materia":"med","nivel":0,"enunciado":"No atestado médico, o código da doença (CID) só deve constar:","opcoes":["Com autorização do paciente ou por dever legal","Sempre, obrigatoriamente","Apenas se o empregador exigir por escrito","Nunca, em hipótese alguma"],"explicacao":"Protege o sigilo médico."},{"id":4721,"materia":"med","nivel":0,"enunciado":"O rastreamento do câncer do colo do útero no SUS é prioritário para mulheres de:","opcoes":["25 a 64 anos","10 a 20 anos","70 a 90 anos","Qualquer idade, todos os meses"],"explicacao":"Que já tiveram atividade sexual."},{"id":4722,"materia":"med","nivel":0,"enunciado":"Uma medida não medicamentosa importante no controle da hipertensão é:","opcoes":["Reduzir o consumo de sal","Aumentar o consumo de álcool","Parar de fazer atividade física","Dormir menos"],"explicacao":"Também ajudam perder peso e praticar exercícios."},{"id":4723,"materia":"med","nivel":0,"enunciado":"Uma hemoglobina glicada (HbA1c) maior ou igual a 6,5% sugere:","opcoes":["Diabetes mellitus","Anemia","Hipertensão","Hipotireoidismo subclínico"],"explicacao":"Confirmada por outro exame alterado."},{"id":4724,"materia":"med","nivel":0,"enunciado":"O método clínico centrado na pessoa busca explorar:","opcoes":["A doença e também a experiência da pessoa com o adoecimento","Apenas os exames laboratoriais","Somente a opinião do especialista sobre o caso clínico","Só os sintomas físicos"],"explicacao":"Inclui sentimentos, ideias, funcionalidade e expectativas."},{"id":4725,"materia":"med","nivel":0,"enunciado":"A longitudinalidade, na atenção primária, é:","opcoes":["O acompanhamento da pessoa pela mesma equipe ao longo do tempo","O atendimento só em emergências","A troca constante de médico","O encaminhamento de todos os casos ao hospital de referência da região"],"explicacao":"Atributo essencial descrito por Barbara Starfield."},{"id":4726,"materia":"med","nivel":0,"enunciado":"O tratamento da tuberculose pulmonar no esquema básico para adultos dura:","opcoes":["6 meses","15 dias","2 anos","1 semana"],"explicacao":"2 meses de RIPE e 4 meses de RI."},{"id":4727,"materia":"med","nivel":1,"enunciado":"São atributos essenciais da atenção primária, segundo Starfield:","opcoes":["Primeiro contato, longitudinalidade, integralidade e coordenação","Especialização, hospitalização, alta tecnologia e atendimento só por agendamento","Atendimento só por demanda espontânea","Exames de imagem, cirurgia e internação"],"explicacao":"Os derivados são orientação familiar, comunitária e competência cultural."},{"id":4728,"materia":"med","nivel":1,"enunciado":"A prevenção quaternária consiste em:","opcoes":["Evitar intervenções desnecessárias e proteger a pessoa do excesso de medicalização","Tratar doenças já instaladas com medicamentos de última geração","Vacinar a população","Reabilitar após um AVC"],"explicacao":"Previne danos causados pelo próprio cuidado."},{"id":4729,"materia":"med","nivel":1,"enunciado":"O genograma e o ecomapa são ferramentas de:","opcoes":["Abordagem familiar","Diagnóstico por imagem","Cirurgia","Cálculo de doses"],"explicacao":"Mostram a estrutura da família e suas relações com a comunidade."},{"id":4730,"materia":"med","nivel":1,"enunciado":"Na dengue, é sinal de alarme:","opcoes":["Dor abdominal intensa e contínua","Febre baixa no primeiro dia","Dor no corpo leve","Manchas avermelhadas sem outros sintomas"],"explicacao":"Também vômitos persistentes, sangramento de mucosas e letargia."},{"id":4731,"materia":"med","nivel":1,"enunciado":"Em um teste de rastreamento, é desejável alta sensibilidade porque:","opcoes":["Assim poucos doentes deixam de ser identificados","O teste fica mais barato","Elimina a necessidade de qualquer exame de confirmação depois","Reduz a prevalência da doença"],"explicacao":"Testes muito sensíveis têm poucos falsos negativos."},{"id":4732,"materia":"med","nivel":1,"enunciado":"O escore CURB-65 é usado para avaliar a gravidade da:","opcoes":["Pneumonia adquirida na comunidade","Insuficiência renal crônica","Fratura de quadril","Depressão"],"explicacao":"Confusão, ureia, frequência respiratória, pressão arterial e idade ≥ 65."},{"id":4733,"materia":"med","nivel":2,"enunciado":"O valor preditivo positivo de um teste diagnóstico depende:","opcoes":["Da prevalência da doença na população testada","Apenas da marca do aparelho e do laboratório que fez o exame","Só da idade do médico","Da hora do exame"],"explicacao":"Com prevalência baixa, aumentam os falsos positivos."},{"id":4734,"materia":"med","nivel":2,"enunciado":"Em morte natural sem assistência médica, em local com Serviço de Verificação de Óbito (SVO), o corpo deve ser:","opcoes":["Encaminhado ao SVO","Encaminhado ao IML","Liberado sem declaração","Cremado imediatamente"],"explicacao":"Mortes violentas ou suspeitas vão para o IML."},{"id":4735,"materia":"med","nivel":2,"enunciado":"A Lei nº 13.595/2018 trata das atribuições do:","opcoes":["Agente Comunitário de Saúde e do Agente de Combate às Endemias","Médico especialista","Farmacêutico hospitalar e do técnico de farmácia nas unidades de pronto atendimento","Fisioterapeuta"],"explicacao":"Profissionais essenciais na APS."},{"id":4736,"materia":"med","nivel":3,"enunciado":"Um tratamento reduz o risco de um evento de 10% para 5%. O número necessário para tratar (NNT) é:","opcoes":["20","5","10","50"],"explicacao":"Redução absoluta de risco de 5% → NNT = 1 ÷ 0,05."},{"id":4737,"materia":"med","nivel":4,"enunciado":"Um teste com sensibilidade muito alta e resultado negativo serve principalmente para:","opcoes":["Descartar a doença","Confirmar a doença","Aumentar a prevalência","Medir a gravidade"],"explicacao":"Regra 'SnNout': sensível, negativo, exclui."},{"id":4738,"materia":"med","nivel":4,"enunciado":"Na consulta, a técnica de 'devolver a pergunta' e resumir o que o paciente disse serve para:","opcoes":["Checar o entendimento e construir um plano em conjunto","Encerrar a consulta mais rápido e reduzir o tempo de espera","Evitar que o paciente fale","Substituir o exame físico"],"explicacao":"Faz parte das habilidades de comunicação clínica."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('sus','enf','fisio','med') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
